  CollectionHall_100460_Desc = {
    Text = "\"Eu já disse antes, não importa os meios, eu levarei todos para casa.\"\n\"Eu queimarei tudo que me pertence, e então...\n\"Com este inferno das estrelas, queimarei este mundo falso, imundo e caótico até as cinzas!\"\n\"Eu declaro isso em nome de Kathigu-Ra!\"\n\"A aurora virá!\""
  },
  CollectionHall_100460_LockTip = {
    Text = "Completar a consciência errante \"Dia Eterno\""
  },
  CollectionHall_100460_Title = {
    Text = "A aurora queima tudo"
  },
  CollectionHall_100461_Desc = {
    Text = "A loucura da morte gira como um caleidoscópio, o doce aroma metálico que surge da doença e dos corpos é o melhor incenso. Você levanta seus copos de longe, separados por incontáveis almas indo para sua morte—se a morte é um destino, que vamos apressadamente a este baile, e juntos, com a batida final da dança, mergulhemos nos portões do Inferno."
  },
  CollectionHall_100461_LockTip = {
