  CollectionHall_100464_LockTip = {
    Text = "Completar \"Banquete Ardente\" na dificuldade Difícil no Errante"
  },
  CollectionHall_100464_Title = {
    Text = "Máscara da praga"
  },
  CollectionHall_100465_Desc = {
