  CollectionHall_120465_LockTip = {
    Text = "Pode ser desbloqueado no Capítulo 4-5"
  },
  CollectionHall_120465_Title = {Text = "Crujido"},
  CollectionHall_120466_LockTip = {
    Text = "Pode ser desbloqueado no: Capítulo 3–10"
  },
  CollectionHall_120466_Title = {
    Text = "Telegrama Silencioso"
  },
  CollectionHall_121154_Title = {Text = "Paraíso"},
  CollectionHall_121341_Desc = {
    Text = "<Título: Introdução>\n A \"princesa\" que aceita a responsabilidade de conceber a \"Criança Santa\" agora é a \"Mãe Divina\", uma figura crucial dentro do culto dos marinheiros.\n Ela também foi uma dama que correu em busca da liberdade, assim como Murphy, registrada por Misaq, que embarcou na jornada de fuga a bordo do Sonanir.\n Mas em um mundo sem o Guardião, o destino quebrou o pescoço nobre do jovem cisne.\n O sangue distorcido a envolve sem resistência, mesmo que liberar seu corpo para a morte não a salve. Ela se força a dizer uma e outra vez \"Eu sou a nobre Mãe Divina\", que é apenas uma sugestão e persuasão para si mesma.\n Só pode obedecer, apenas obedecer. Obedecer à falsa profecia, obedecer ao absurdo destino, e então, a partir do amargo infinito, saborear com dificuldade um vislumbre da doce ilusão."
  },
  CollectionHall_121341_LockTip = {
    Text = "Desbloqueado após despertar \"Delírio de Nascimento·Murphy\""
  },
  CollectionHall_121341_Title = {
    Text = "Murphy: fauxborn"
  },
  CollectionHall_121381_Desc = {
    Text = "Você trocou mil bolotas por uma história de outro mundo. \n Uma história sobre heróis e deuses demoníacos, vigilância e perseverança. \n Uma história sobre resignação e saudade, velhos amigos e novos amigos. \n Uma história que já foi contada."
  },
  CollectionHall_121381_LockTip = {
    Text = "Finalizar a Conexão Multidimensional \"Turno inverso\""
  },
  CollectionHall_121381_Title = {
    Text = "Resonância da Pousada dos Fenômenos"
  },
  CollectionHall_121382_Desc = {
    Text = "Muito tempo depois, ele e ele finalmente tiveram uma balada cantada. \n Sobre a redenção da ressuscitação, sobre as almas gêmeas."
  },
  CollectionHall_121382_LockTip = {
    Text = "Completar \"Além do Horizonte - Parte 2\" na Visão de Sonhos Estranhos"
  },
  CollectionHall_121382_Title = {
    Text = "Poema do Pássaro Sem Asas"
  },
  CollectionHall_121383_Desc = {
    Text = "O jovem pagou o preço exigido por tudo que é efêmero. \n Agora, restam apenas o silêncio do poder e sua companhia. \n O rei está prestes a adormecer, e ele encontrará o fim do mundo em seu sonho."
  },
  CollectionHall_121383_LockTip = {
    Text = "Completar a consciência do errante \"Dia da Coroação\""
  },
  CollectionHall_121383_Title = {
    Text = "Reino Eterno de Dor Sem Fim"
  },
  CollectionHall_121384_Desc = {
    Text = [[
Elas o cercam, elas o admiram, elas o acompanham.
Elas levantam vela para o Deus Criador.]]
  },
  CollectionHall_121384_LockTip = {
    Text = "Conclua a Operação de Investigação 9-11 para desbloquear"
  },
  CollectionHall_121384_Title = {
    Text = "Levantar vela ao deus criador"
  },
  CollectionHall_121385_Desc = {
    Text = "Aquelas são asas renascidas da destruição, asas que conquistaram a liberdade através do sacrifício.\nA profecia do destino já se cumpriu, ele jurou em dor e arrependimento que a dívida de sangue deve ser paga com sangue."
  },
  CollectionHall_121385_LockTip = {
    Text = "Completar \"Além do horizonte · baixo\" na Visão de Sonhos Estranhos"
  },
  CollectionHall_121385_Title = {
    Text = "Quando a tempestade se levanta"
  },
  CollectionHall_121386_Desc = {
    Text = "No início do sonho absurdo e caótico, Ele estava destinado a enfrentar seu destino. \n Mas Ele já passou por demais e definiu demais. \n Ele decidiu, com a maior racionalidade que a humanidade pode manter, observar sua origem, aquela divindade suprema."
  },
  CollectionHall_121386_LockTip = {
    Text = "Conclua a Operação de Investigação 9-11 para desbloquear"
  },
  CollectionHall_121386_Title = {
    Text = "Batalha do Destino Primal"
  },
  CollectionHall_121387_Desc = {
    Text = "Ganhar, perder, cortar, sacrificar. \n O herói pagou o preço total, e o poder de proteger os tesouros é sua recompensa."
  },
  CollectionHall_121387_LockTip = {
    Text = "Concluir a Operação de Investigação 9-13 para desbloquear"
  },
  CollectionHall_121387_Title = {
    Text = "Olho sem pupilo"
  },
  CollectionHall_121388_Desc = {
    Text = "Ele colocou a coroa sobre si mesmo, ele colocou as algemas sobre si mesmo.\nEra um calor efêmero e ilusório, era a glória do passado destinada à ruína."
  },
  CollectionHall_121388_LockTip = {
    Text = "Completar a consciência do errante \"Dia da Coroação\""
  },
  CollectionHall_121388_Title = {
    Text = "A Jornada Solitária do Jovem Rei"
  },
  CollectionHall_121389_Desc = {
    Text = "Apesar da situação estar contra você, o canto da sua boca já se levantou levemente. \n \"Meu turno, comprar carta!\" \n Não importa se é na Pousada dos fenômenos ou em Misaq, \n subestimar a capacidade de dano do suporte pode custar caro! Ignatius!"
  },
  CollectionHall_121389_LockTip = {
    Text = "Finalizar a Conexão Multidimensional \"Turno inverso\""
  },
  CollectionHall_121389_Title = {
    Text = "Meu momento de reverter o curso!"
  },
  CollectionHall_121390_Desc = {
    Text = "Uma lenda completa não pode faltar a transformação de inimigos em amigos."
  },
  CollectionHall_121390_LockTip = {
    Text = "Concluir a Operação de Investigação · Dificuldade 9-10 para desbloquear"
  },
  CollectionHall_121390_Title = {
    Text = "inimigo, amigo"
  },
  CollectionHall_121391_Desc = {
    Text = "De agora em diante, você se ergue como Guardião entre a miríade de estudantes e acadêmicos da Misaq."
  },
  CollectionHall_121391_LockTip = {
    Text = "Concluir a Operação de Investigação · Difícil 9-11 para desbloquear"
  },
  CollectionHall_121392_Desc = {
    Text = "Podemos ser um instante na eternidade, grãos de areia na correnteza. \n No entanto, a vida comum é a nossa preciosa eternidade, pois não importa quão louco e caótico o mundo se torne — \n a dignidade humana se baseia na luz da razão."
  },
  CollectionHall_121392_LockTip = {
    Text = "Conclua Operação de Investigação 9-11 para desbloquear"
  },
  CollectionHall_121392_Title = {
    Text = "Canto do Tempo Eterno"
  },
  CollectionHall_121393_Desc = {
    Text = "Os heróis mergulharam em contos de fadas, cada conto é igual, com animais, demônios, fadas e o desconhecido. \n Além da breve liberdade e dos desejos ilusórios, no fim do conto de fadas, esconde-se um coração falso imposto a ele."
  },
  CollectionHall_121393_LockTip = {
    Text = "Completar \"Além do Horizonte · baixo\" na Visão de Sonhos Estranhos"
  },
  CollectionHall_121393_Title = {
    Text = "Voo para a Via Láctea"
  },
  CollectionHall_121394_Desc = {
    Text = "Aqui é a Pousada dos fenômenos, localizada na Fenda Espacial de outro mundo.\nPortais conectando diferentes universos piscam com a luz das estrelas, dando as boas-vindas à sua chegada.\nEspere... O que você está fazendo aqui, Guardião?"
  },
  CollectionHall_121394_LockTip = {
    Text = "Finalizar a conexão multidimensional \"Turno inverso\""
  },
  CollectionHall_121394_Title = {
    Text = "Bem-vindo à Pousada dos fenômenos!"
  },
  CollectionHall_121395_Desc = {
    Text = "A lâmina afiada de Misaq garantirá a vitória nesta partida para você. \n O vínculo entre você e seu parceiro é inquebrável. \n Mesmo que um dia vocês estejam em universos diferentes, isso não mudará."
  },
  CollectionHall_121395_LockTip = {
    Text = "Finalizar a Conexão Multidimensional \"Turno inverso\""
  },
  CollectionHall_121395_Title = {
    Text = "Misaq Lâmina afiada!"
  },
  CollectionHall_121396_Desc = {
    Text = "\"Você não fez o Treinamento diário? Que tal jogar uma partida de Carta do Mundo primeiro!\"\n\"Você não jogou na Zona Proibida de Catástrofe de Fusão? Que tal jogar uma partida de Carta do Mundo primeiro!\"\n\"Isto é Fase de Duelo, não Carta do Mundo! Eu vou coletar mil bolotas para você ver!\""
  },
  CollectionHall_121396_LockTip = {
    Text = "Finalizar a conexão multidimensional \"Reverter o turno\""
  },
  CollectionHall_121396_Title = {
    Text = "Vamos brincar de Carta do Mundo!"
  },
  CollectionHall_121397_Desc = {
    Text = "Chame meu nome, antes do amanhecer esquecido."
  },
  CollectionHall_121397_LockTip = {
    Text = "Concluir a operação de investigação · Difícil 9-11 para desbloquear"
  },
  CollectionHall_121397_Title = {
    Text = "Vindo do esquecimento@2"
  },
  CollectionHall_121398_Desc = {
    Text = "\"Venha assinar um contrato comigo e torne-se o Mestre das Cartas!\"\nEsta pessoa, uma bela menina dragão do outro mundo, fez a você um convite caloroso e inexplicável.\nPara que este pequeno incidente no espaço de fase volte ao normal o mais rápido possível, você não tem outra escolha."
  },
  CollectionHall_121398_LockTip = {
    Text = "Finalizar a conexão multidimensional \"Reverter o turno\""
  },
  CollectionHall_121398_Title = {
    Text = "Dona da Pousada, Ignatius!"
  },
  CollectionHall_121399_Desc = {
    Text = "Os que vierem depois encontrarão uma nota de rodapé sob um pesado presente. \n A única pessoa que escapou de se tornar um herói se tornou um herói, e o filho que valoriza os amigos só tem um único amigo restante."
  },
  CollectionHall_121399_LockTip = {
    Text = "Completar a consciência do errante \"Dia da Coroação\""
  },
  CollectionHall_121399_Title = {
    Text = "Vou seguir sozinho"
  },
  CollectionHall_121400_Desc = {
    Text = "Afaste-se do Senhor, enfrente o Senhor, desafie o Senhor.\nSua história é desconhecida por ninguém, sua memória perdurará para sempre."
  },
  CollectionHall_121400_LockTip = {
    Text = "Concluir a Operação de Investigação 9-13 para desbloquear"
  },
  CollectionHall_121400_Title = {
    Text = "Senhor da Estupidez da Criação"
  },
  CollectionHall_121401_Desc = {
    Text = "Nada mais faz sentido, portanto você pode estar aqui. \n Tudo o que passou é a totalidade do significado que você definiu, por isso você está aqui."
  },
  CollectionHall_121401_LockTip = {
    Text = "Concluir a Operação de Investigação 9-13 para desbloquear"
  },
  CollectionHall_121401_Title = {
    Text = "existencialismo"
  },
  CollectionHall_121402_Desc = {
    Text = "O caminho para Eles, o caminho longe de Eles. \n Tudo está prestes a se separar, tudo está prestes a terminar, tudo está prestes a começar. \n A sombra diante da porta começou, então, uma longa espera, esperando que a Chave de Prata guie seu caminho de volta."
  },
  CollectionHall_121402_LockTip = {
    Text = "Concluir a Operação de Investigação 9-13 para desbloquear"
  },
  CollectionHall_121402_Title = {
    Text = "Caminho para Eles"
  },
  CollectionHall_121403_Desc = {
    Text = "As linhas de possibilidades d'Ele, separação, convergência, desintegração.\nAté que chegou o único salvador, até que finalmente entraram no único fim."
  },
  CollectionHall_121403_LockTip = {
    Text = "Concluir a Operação de Investigação · Difícil 9-10 para desbloquear"
  },
  CollectionHall_121403_Title = {
    Text = "O único fim"
  },
  CollectionHall_121404_Desc = {
    Text = "O jovem rei aceitou a transação. \n Ele disse: Meu reino estará em segurança."
  },
  CollectionHall_121404_LockTip = {
    Text = "Completar a consciência do errante \"Dia da Coroação\""
  },
  CollectionHall_121404_Title = {
    Text = "Cerimônia de Coroação"
  },
  CollectionHall_121405_Desc = {
    Text = "Dentro dessa Fenda Espacial quebrada, existia a lendária Pousada dos fenômenos. \n Portais que conectavam diferentes universos, que parpadeavam com as vastas estrelas, que recebiam cada Mestre das Cartas. \n E você é a prova de que tudo isso existiu."
  },
  CollectionHall_121405_LockTip = {
    Text = "Finalizar a conexão multidimensional \"Turno inverso\""
  },
  CollectionHall_121405_Title = {
    Text = "Adeus, Mestre das Cartas!"
  },
  CollectionHall_121406_Desc = {
    Text = "O Senhor olha para você, você rompeu os olhos do Senhor."
  },
  CollectionHall_121406_LockTip = {
    Text = "Concluir a Operação de Investigação 9-13 para desbloquear"
  },
  CollectionHall_121406_Title = {
    Text = "Visão do Fim"
  },
  CollectionHall_121407_Desc = {
    Text = "Guerreiro, vingador, escravo, senhor, mercador. \n Mesma posição? Posição diferente? Mesma posição."
  },
  CollectionHall_121407_LockTip = {
    Text = "Conclua a Operação de Investigação 9-11 para desbloquear"
  },
  CollectionHall_121407_Title = {
    Text = "Canção da Multiplicidade"
  },
  CollectionHall_121408_Desc = {
    Text = "Você sabe que não está lutando por algo grandioso. \n Para escapar das aulas, para os deveres de casa, para as sobremesas, para os amigos, para o fogão, para passar o tempo. \n Você é apenas uma pessoa comum, destinada a morrer no dia a dia."
  },
  CollectionHall_121408_LockTip = {
    Text = "Concluir a Operação de Investigação · Difícil 9-11 para desbloquear"
  },
  CollectionHall_121408_Title = {
    Text = "Para aqueles que morrem no dia a dia"
  },
  CollectionHall_121409_Desc = {
    Text = "Os animais, todos os animais superiores, são inevitavelmente controlados pelo comportamento social. \n No entanto, ela se lançou pessoalmente à morte, como desejava, para desconstruir a verdade. \n Uma gênio louca e sem igual, ela preferiu trazer a destruição com suas próprias mãos, concedendo a todos a isenção de consumir o veneno chamado esperança."
  },
  CollectionHall_121409_LockTip = {
    Text = "Concluir a Operação de Investigação 9-13 para desbloquear"
  },
  CollectionHall_121409_Title = {
    Text = "Desconstrução do Comportamento Comunitário"
  },
  CollectionHall_121410_Desc = {
    Text = "Ele envia das alturas águas amargas em um fluxo incessante, reunindo-se, reunindo-se. \n Finalmente, antes de se fundir com nossa carne e sangue, é o rio que deve ser percorrido."
  },
  CollectionHall_121410_LockTip = {
    Text = "Completar \"Além do horizonte · baixo\" na Visão de Sonhos Estranhos"
  },
  CollectionHall_121410_Title = {
    Text = "Riacho amargo"
  },
  CollectionHall_121411_Desc = {
    Text = "Elas se despedem com a expectativa do reencontro. \n Pois esta é uma pessoa muito querida, pois esta é a morte de uma pessoa muito querida que não era destinada."
  },
  CollectionHall_121411_LockTip = {
    Text = "Conclua a Operação de Investigação 9-11 para desbloquear"
  },
  CollectionHall_121411_Title = {
    Text = "Morte de uma raridade"
  },
  CollectionHall_121412_Desc = {
    Text = "Descanse um pouco, respire. \n Mesmo enfrentando um tema como o fim do mundo, nem todos têm a oportunidade de lidar com três mentores tão importantes ao mesmo tempo."
  },
  CollectionHall_121412_LockTip = {
    Text = "Concluir a Operação de Investigação 9-13 para desbloquear"
  },
  CollectionHall_121412_Title = {
    Text = "Intervalo do ato"
  },
  CollectionHall_121413_Desc = {
    Text = "A história de mil bolotas deve sempre começar com a primeira. \n Em Fase de Duelo, cada vez que você dispara uma carta, \n uma faísca de lembrança dourada passa inexplicavelmente pelos olhos de Ignatius."
  },
  CollectionHall_121413_LockTip = {
    Text = "Finalizar a conexão multidimensional \"Turno inverso\""
  },
  CollectionHall_121413_Title = {
    Text = "Reabastecimento ilimitado!"
  },
  CollectionHall_121414_Desc = {
    Text = "Loucura, o prelúdio da destruição, essa é a lógica subjacente de um mundo ordenado. \n Ele irá destruir? O mundo irá se destruir? \n Ninguém sabe. \n Mas diante do Deus Criador, a loucura está nutrindo o novo nascido entre Ele e o mundo."
  },
  CollectionHall_121414_LockTip = {
    Text = "Conclua a Operação de Investigação 9-11 para desbloquear"
  },
  CollectionHall_121414_Title = {
    Text = "Loucura Fuga"
  },
  CollectionHall_121415_Desc = {
    Text = "O que é o mais irracional do mundo? \n Ele não tem propósito, não se importa com ressentimentos, não distingue o bem do mal. \n Ele só quer, ao acordar, transformar tudo o que surgiu no sonho em pó."
  },
  CollectionHall_121415_LockTip = {
    Text = "Concluir a Operação de Investigação 9-13 para desbloquear"
  },
  CollectionHall_121415_Title = {
    Text = "farinha de carne"
  },
  CollectionHall_121416_Desc = {
    Text = "Como aquele fragmento único, tornar-se um deus é fácil.\nEntão, qual é o preço?"
  },
  CollectionHall_121416_LockTip = {
    Text = "Concluir a Operação de Investigação 9-13 para desbloquear"
  },
  CollectionHall_121416_Title = {
    Text = "tornar-se um deus"
  },
  CollectionHall_121417_Desc = {
    Text = "Ao longo da longa civilização humana, construímos muitas coisas. \n Sobre a matéria, sobre o espírito, sobre a sobrevivência, o amor, a fumaça e os conflitos. \n Mas isso é apenas um ruído insignificante no sonho do criador, e uma ficção negligenciada de ser desvendada."
  },
  CollectionHall_121417_LockTip = {
    Text = "Concluir a Operação de Investigação 9-13 para desbloquear"
  },
  CollectionHall_121417_Title = {
    Text = "Conjunto fictício"
  },
  CollectionHall_121418_Desc = {
    Text = "O guardião mais covarde da história de Misaq morreu em meio a uma imensa felicidade."
  },
  CollectionHall_121418_LockTip = {
    Text = "Concluir a Operação de Investigação · Difícil 9-11 para desbloquear"
  },
  CollectionHall_121418_Title = {
    Text = "O herói decidido a fugir"
  },
  CollectionHall_121898_LockTip = {
    Text = "Desbloqueio após concluir a Operação de Investigação - Capítulo das Estrelas 4-0"
  },
  CollectionHall_121898_Title = {
    Text = "Peregrinação da Ilusão Eterna"
  },
  CollectionHall_121901_LockTip = {
    Text = "Concluir a operação de investigação Crônica das Estrelas 4-16 para desbloquear"
  },
  CollectionHall_121901_Title = {
    Text = "Nascimento do Divino em sete dias"
  },
  CollectionHall_122565_LockTip = {
    Text = "Limpar qualquer fase do evento por tempo limitado \"Sacramento Envolto em Névoa: O Eu Perdido\""
  },
  CollectionHall_122565_Title = {
    Text = "Sacramento Envolto em Névoa: O Eu Perdido"
  },
  CollectionHall_123756_Title = {
    Text = "Batismo de Prata e Sangue"
  },
  CollectionHall_124124_Desc = {
    Text = "Você tem a possibilidade de encontrar um segundo rosto de muitas existências, mesmo que seja um infante que não deveria existir ou um nascido de uma divindade falha."
  },
  CollectionHall_124124_LockTip = {
    Text = "Desbloquear a Operação de Investigação Capítulo Estelar 4-16"
  },
  CollectionHall_124124_Title = {Text = "Lado Dois"},
  CollectionHall_124125_Desc = {
    Text = "Oh... então há um final ainda pior."
  },
  CollectionHall_124125_LockTip = {
    Text = "Desbloquear a Operação de Investigação Capítulo Estelar 4-16"
  },
  CollectionHall_124125_Title = {
    Text = "A Morte dela, dele e dele"
  },
  CollectionHall_124126_Desc = {
    Text = "Como você descreveria um companheiro que parte quando está radiante demais? \n Não descreva seu brilho; descreva seus braços e o cheiro de cedro que você sente neles."
  },
  CollectionHall_124126_LockTip = {
    Text = "Desbloquear a Operação de Investigação Capítulo Estelar 4-16"
  },
  CollectionHall_124126_Title = {Text = "Cedar"},
  CollectionHall_124127_Desc = {
    Text = "No fim da jornada, você sabe quem está esperando por você. \n Mas você ainda não escapou; você cai do céu novamente."
  },
  CollectionHall_124127_LockTip = {
    Text = "Desbloquear a Operação de Investigação: Difícil Crônica das Estrelas 4-10"
  },
  CollectionHall_124127_Title = {Text = "Cair"},
  CollectionHall_124128_Desc = {
    Text = "As crianças não pertencem à Mãe; elas decidiram que todos devem ficar aqui. \n Fiquem no seu eternamente doce paraíso."
  },
  CollectionHall_124128_LockTip = {
    Text = "Desbloquear a Operação de Investigação: Difícil Crônica das Estrelas 4-10"
  },
  CollectionHall_124128_Title = {
    Text = "Doce Paraíso"
  },
  CollectionHall_124129_Desc = {
    Text = "Você não teve tempo de salvá-la; ela não escapou. \n Ela foi devorada, deixada impotente e isolada, e amarrou um cordão umbilical falso ao redor de si mesma."
  },
  CollectionHall_124129_LockTip = {
    Text = "Desbloquear a Operação de Investigação Capítulo Estelar 4-16"
  },
  CollectionHall_124129_Title = {
    Text = "Cordão Umbilical Falso"
  },
  CollectionHall_124130_Desc = {
    Text = "3.14159@2, 3.141592@3, 3.14159265@4...\nUm círculo sem fim na neve, um pi cruel e interminável."
  },
  CollectionHall_124130_LockTip = {
    Text = "Desbloquear a Operação de Investigação: Difícil Crônica das Estrelas 4-10"
  },
  CollectionHall_124130_Title = {
    Text = "\"3.14159@4\""
  },
  CollectionHall_124131_Desc = {
    Text = "Você está atrasado novamente. Não fique enrolando, apresse-se, ainda mais rápido. \n Corra para o próximo resultado."
  },
  CollectionHall_124131_LockTip = {
    Text = "Desbloquear a Operação de Investigação Capítulo Estelar 4-16"
  },
  CollectionHall_124131_Title = {
    Text = "Um certo fim"
  },
  CollectionHall_124132_Desc = {
    Text = "Me abrace, meu querido bebê, meu... pai, meu destino."
  },
  CollectionHall_124132_LockTip = {
    Text = "Desbloquear a Operação de Investigação: Difícil Crônica das Estrelas 4-10"
  },
  CollectionHall_124132_Title = {
    Text = "No Útero Escuro de Sua Filha"
  },
  CollectionHall_124133_Desc = {
    Text = "O céu está prestes a clarear, vamos nos despedir de ontem.\nAdeus à dor, à absurdidade e à confusão de ontem,\ne dar boas-vindas a um amanhã mais brilhante, cada um seguindo seu próprio caminho."
  },
