  CollectionHall_124141_Desc = {
    Text = "Ela e ela compartilham sua devoção, enquanto ele e ele têm sua rebelião e lealdade. \n Ela tece uma grande mentira, e ele, ele, ela e ela participam dela. \n Em casa, todos formam uma família doce e inseparável."
