  CollectionHall_129803_Title = {
    Text = "Trem de Alegria Acelerado: Partida"
  },
  CollectionHall_129810_Desc = {
    Text = "Em um ciclo que não pode ser registrado, Ramona: Desgastada atravessou o canteiro de flores atrás do relógio. \n Com o canto do olho, ela avistou o jardim de rosas, onde flores vibrantes estavam desabrochando. \n Após um raro momento de pausa, ela abandonou todos os pensamentos fúteis e continuou em direção ao campo de batalha final. \n A lama espirrava nas pétalas de flores vermelhas como sangue, sendo rapidamente devorada pela lama corrosiva, deixando apenas a silhueta orgulhosa ao vento."
  },
  CollectionHall_129810_Title = {
    Text = "A rosa que pisa na lama"
  },
  CollectionHall_130218_LockTip = {
    Text = "Concluir qualquer Fase do evento por tempo limitado \"Renascimento de cabeça para baixo: Notas da câmara escura\""
