  CollectionHall_133770_Desc = {
    Text = "Saudações, passageiros!\nA Festa de Oração está se aproximando! Nesta alegre estação de reencontros e novos começos, toda a nossa tripulação estende os mais sinceros Desejos a todos vocês, viajantes cansados que fazem a longa jornada de volta para casa:\n\nDesejamos a vocês uma feliz Festa de Oração, alegres reuniões em família, uma viagem rápida e o melhor de tudo! <(￣︶￣)↗[GO!]"
  },
