  },
  CollectionHall_133771_Desc = {
    Text = "Atenção passageiros, lamentamos informar que devido ao humor do condutor, este expresso fará uma parada não programada aqui. Anunciaremos o horário exato de partida pelo sistema de som assim que o massacre mútuo tiver sido concluído.\nDurante esta parada, o ar-condicionado, a iluminação e os banheiros permanecerão em pleno funcionamento. Por favor, utilize-os a seu critério com base em suas necessidades de massacre, de modo a evitar não estar em perigo.\nAfinal, o único dever do expresso da alegria é trazer risadas a todos os nossos passageiros! ~(￣▽￣~)(~￣▽￣)~"
  },
  CollectionHall_133771_LockTip = {
