  CollectionHall_142154_Title = {Text = "Cidade"},
  CollectionHall_142155_Desc = {
    Text = "Quando pressionado por algo disforme, incompreensível, irreconhecível e repugnante, lançar um ATQ defensivo é o instinto dos seres vivos.\nPortanto, isso não pode ser considerado um pecado."
