  CollectionHall_142155_Title = {
    Text = "Brutalidade Inocente"
  },
  CollectionHall_142156_Desc = {
    Text = "\"Você consegue ouvir minha voz? Mesmo que minha silhueta se dissolva no vento.\"\nUm chamado distante chega pelo vento — uma voz que atravessa o tempo, vinda de uma noite de inverno vasta e fria, da outra margem do esquecimento."
  },
  CollectionHall_142156_LockTip = {
    Text = "Concluir Conexão multidimensional \"Sementes esquecidas de amor\""
  },
  CollectionHall_142156_Title = {
    Text = "忘却の彼方"
  },
  CollectionHall_142157_Desc = {
    Text = "As memórias piscam e se sobrepõem, e a veracidade do desfecho permanece incerta.\nMas isso realmente importa?\nAfinal, nem todas as histórias precisam começar com amor, mas todas terão a morte como ponto final."
  },
  CollectionHall_142157_LockTip = {
    Text = "Concluir Conexão multidimensional \"Sementes esquecidas de amor\""
  },
  CollectionHall_142157_Title = {
    Text = "Quatro Memórias"
  },
  CollectionHall_142158_Desc = {
    Text = "Se um dia você também, como eu, se encontrar imerso em um cenário de Carne e sangue confusa, podridão e decomposição.\nEntão você certamente será capaz de compreender —\nO instante em que as pontas delicadas dos dedos Dela tocam os meus é um milagre raro neste mundo."
  },
  CollectionHall_142158_LockTip = {
    Text = "Concluir Conexão multidimensional \"Sementes esquecidas de amor\""
  },
  CollectionHall_142158_Title = {Text = "Milagre"},
  CollectionHall_142159_Desc = {
    Text = "Você também está cansado da vida comum, cíclica, monótona e repetitiva?\nExperimente algo novo — outro horizonte está escancarando suas fauces, enviando a você um convite de boas-vindas."
  },
  CollectionHall_142159_LockTip = {
    Text = "Concluir Conexão multidimensional \"Sementes esquecidas de amor\""
  },
  CollectionHall_142159_Title = {
    Text = "Reino de Sangue"
  },
  CollectionHall_142160_Desc = {
    Text = "O amor é sublime, o amor é Ganância; o amor é Bênção, o amor é maldição.\nO amor nasce com a água e com a água também há de perecer.\nMas a estação das chuvas não voltará mais."
  },
  CollectionHall_142160_LockTip = {
    Text = "Concluir Conexão multidimensional \"Sementes esquecidas de amor\" na Dificuldade difícil"
  },
  CollectionHall_142160_Title = {
    Text = "Estação das Chuvas"
  },
  CollectionHall_142161_Desc = {
    Text = "Toda Vida nasce na ignorância, extrai nutrientes de todas as coisas, transforma o ambiente, saqueia recursos e se alimenta de si mesma.\nEste é o pecado original do qual não há escapatória."
  },
  CollectionHall_142161_LockTip = {
    Text = "Concluir Conexão multidimensional \"Sementes esquecidas de amor\""
  },
  CollectionHall_142161_Title = {
    Text = "Pecado Original"
  },
  CollectionHall_142162_Desc = {
    Text = "Existe uma planta chamada dente-de-leão, que deixa suas sementes flutuarem ao vento.\nAs sementes felpudas vagam com o vento, muito longe de sua terra natal.\nSolitária, quando ela decidirá seu destino?\nEsse momento é quando, no deserto, há uma única pessoa que ama aquele dente-de-leão."
  },
  CollectionHall_142162_LockTip = {
    Text = "Concluir Conexão multidimensional \"Sementes esquecidas de amor\""
  },
  CollectionHall_142162_Title = {
    Text = "Para Onde Vai o Dente-de-leão"
  },
  CollectionHall_142163_Desc = {
    Text = "Céu vasto, mar de areia sem fim.\nUm lugar deserto onde só existimos eu e você.\nUma errância eterna e livre do amor."
  },
  CollectionHall_142163_LockTip = {
    Text = "Concluir Conexão multidimensional \"Sementes esquecidas de amor\""
  },
  CollectionHall_142163_Title = {
    Text = "Vagando pelo Mar de Areia"
  },
  CollectionHall_142164_Desc = {
    Text = "Posso Chamar o seu nome? Mesmo que o mundo desapareça.\"\nSe todas as memórias forem aniquiladas, o esquecimento negro irá Devorar todos os momentos que não puderam ser lamentados.\nEntão, dê-me a mão, e deixe a luz prateada criar um Elo entre nós.\nEm um novo sonho, na primavera suave em que as tenras sementes brotam."
  },
  CollectionHall_142164_LockTip = {
    Text = "Concluir Conexão multidimensional \"Sementes esquecidas de amor\""
  },
  CollectionHall_142164_Title = {
    Text = "Song of Memento"
  },
  CollectionHall_142165_Desc = {
    Text = "Cante alto, a Vida radiante louva a liberdade, semeando o Gineceu da esperança por toda a terra alcançada."
  },
  CollectionHall_142165_LockTip = {
