  CollectionHall_48618_Title = {Text = "Prólogo"},
  CollectionHall_48619_Desc = {
    Text = "<Title:Data de Fundação>\nA.F.186\n\n<Title:Fundador>\nPaíses Signatários do \"Acordo Mythia\"\n\n<Title:Visão Geral>\nUma organização global composta por humanos comuns.\nEstabelecida com financiamento de vários governos nacionais, opera de forma independente e atua como o gestor oficial e primeiro respondente a fenômenos D.\nA maioria dos membros são indivíduos comuns sem formação em misticismo ou habilidades sobrenaturais, com a missão primária e objetivo único de combater a Dissolução.\nNumerosos escritórios foram estabelecidos em vários países, cada um responsável por diferentes regiões.\nSérios e rigorosos são as primeiras impressões de todos sobre a organização, com seus uniformes brancos excessivamente branqueados tão rígidos quanto sua postura."
