  CollectionHall_48635_Desc = {
    Text = "<Title:Perfil>\nDecana interina de Mythag.\nAprendiz sob Crowley McKinnon, um júnior direto de Herbert.\nUma das testemunhas do assassinato de seu mentor por Herbert, ela gerencia os assuntos da academia desde a morte do mentor.\nUma fanática absoluta por eficiência, nunca se atrasa e mantém o cabelo curto para economizar tempo na aparência.\nFugiu de sua terra natal devastada pela guerra, Elche, para Leo.\nSeu dedo indicador direito não pode se dobrar corretamente, supostamente devido a tratamento brutal em um campo de concentração."
