  CollectionHall_48635_Title = {Text = "Czort"},
  CollectionHall_48636_Desc = {
    Text = "<Title:Introdução>\nUma dos três fundadores, ao lado de Ward Phillips e Kralarques, estabeleceu o predecessor da Universidade Mythag—o Colégio Mythag.\nEla é a primeira \"Despertadora\" e a fonte da tecnologia dos Despertadores.\nGuardando o Poço Negro por muitos anos, muito poucas pessoas viram seu rosto, tornando-a um dos maiores segredos da Universidade Mythag.\n\"Shh... não investigue seu @2.\""
