  },
  CollectionHall_48995_Title = {
    Text = "<WhiteQuality:Capacete de Mergulho>"
  },
  CollectionHall_48996_Desc = {
    Text = "Ver o invisível, ouvir o inaudível"
  },
  CollectionHall_48996_Title = {Text = "Epifania"},
  CollectionHall_48997_Desc = {
    Text = "A origem de todo mal"
  },
  CollectionHall_48997_Title = {Text = "Punição"},
  CollectionHall_48998_Desc = {
    Text = "Tudo se torna meu"
  },
  CollectionHall_48998_Title = {Text = "Gula"},
  CollectionHall_48999_Desc = {
    Text = "Não veja o passado, não pense no futuro"
