  },
  CollectionHall_49000_Title = {Text = "Favor"},
  CollectionHall_49001_Desc = {
    Text = "Acumulado por muito tempo, agora declaro—"
  },
  CollectionHall_49001_Title = {Text = "Emergir"},
  CollectionHall_49002_Desc = {
    Text = "Chamar pelo nome: Eryx"
  },
  CollectionHall_49002_Title = {Text = "Delírio"},
  CollectionHall_49003_Desc = {
    Text = "Conversando com \"Ele.\""
  },
  CollectionHall_49003_Title = {Text = "Sussurro"},
  CollectionHall_49004_Desc = {
    Text = "Conceda a bênção do broto e do embrião"
  },
  CollectionHall_49004_Title = {Text = "Esperança"},
  CollectionHall_49015_Desc = {
    Text = "Após a catástrofe desaparecer repentinamente e a crise ser temporariamente resolvida, a equipe de Operação Especial de Misaq deixou Akutê com uma \"Recompensa inesperada\".\nA Srta. Dexter olhou para trás uma última vez para a enorme cratera no centro da explosão, onde brotos de plantas desconhecidas haviam surgido silenciosamente do solo, sem que ninguém soubesse quando.\nEla respirou aliviada, sentindo-se contente.\nAkutê logo verá sua primavera.\nOs salgueiros brotarão na próxima primavera, e os lírios do vale florescerão silenciosamente após a próxima estação de chuvas, toda a Vida acolherá um novo nascido.\nE a jornada deles contra o desconhecido também começará um novo capítulo.\n"
  },
  CollectionHall_49015_Title = {
    Text = "Primavera em Acushnet"
  },
  CollectionHall_49018_Desc = {
    Text = "A.F. 314, em uma noite profunda de inverno, o som da explosão ecoou pela floresta de Akutê. \n A terra tremeu, a floresta brilhava como se fosse dia. Junto com o grito agudo da vida e o lamento da natureza, a vila foi reduzida a pó. \n Segundo Dexter, um aluno do Departamento de Despertar que participou da \"Investigação da Catástrofe de Akutê\", naquela noite de chamas que subiam ao céu, brilhavam cores de preto e prata."
  },
  CollectionHall_49018_Title = {
    Text = "Pôr do Sol"
  },
  CollectionHall_49025_Desc = {
    Text = "Sacrifício de Sangue Negro Espesso, que os gêmeos abençoem sua carne."
  },
  CollectionHall_49025_Title = {
    Text = "Gêmeos Distorcidos·preto"
  },
  CollectionHall_49026_Desc = {
    Text = "Bênção da Névoa Branca, que os gêmeos protejam sua alma."
  },
  CollectionHall_49026_Title = {
    Text = "Gêmeos Distorcidos·Branco"
  },
  CollectionHall_49027_Desc = {
    Text = "Desfrutem da festa, entre as canções, celebrando a destruição da pátria."
  },
  CollectionHall_49027_Title = {
    Text = "Festa Distante"
  },
  CollectionHall_49028_Desc = {
    Text = "O lendário criador original dos fantoches os nutriu com sangue."
  },
  CollectionHall_49028_Title = {
    Text = "Pulsação Escarlate"
  },
  CollectionHall_49029_Desc = {
    Text = "As máquinas são absolutamente puras, e o divino é supremo. \n O que veio não é um fio, mas a grande Ariadne."
  },
  CollectionHall_49029_Title = {
    Text = "Descida Mecânica"
  },
  CollectionHall_49030_Desc = {
    Text = "Procriem, procriem. Deixem as almas com o sangue da Árvore Mãe se espalharem pelo mundo"
  },
  CollectionHall_49030_Title = {
    Text = "Reevolução"
  },
  CollectionHall_49031_Desc = {
    Text = "O lendário primeiro criador dos autômatos, que os matou com suas próprias mãos."
  },
  CollectionHall_49031_Title = {
    Text = "Abraço Escarlate"
  },
  CollectionHall_49033_Desc = {
    Text = "As cordas do tempo se rompem, as teclas fluentes se despedaçam.\nEles estão além da realidade, remendando o incompleto com a realidade, fazendo a sinfonia eterna soar novamente nos céus.\nQuanto às lágrimas que caem ao despertar do sonho, ninguém sabe para onde vão"
  },
