  CollectionHall_51019_Desc = {
    Text = "<Title:Data de Fundação>\nAntes do Grande Dilúvio\n\n<Title:Fundador>\nDesconhecido\n\n<Title:Visão Geral>\nUm povo nômade que se fragmentou do Império Assírio.\nEscondidos em meio às severas tempestades do Deserto Lemwash, vivem de maneira muito primitiva, raramente se comunicando com forasteiros. O povo Aram venera a \"Árvore Mãe da Abundância,\" dependendo de suas extraordinárias habilidades reprodutivas juntamente com a água do rio sagrado para manter sua população.\nApós o \"Incidente Lemwash,\" o povo Aram desapareceu sem deixar vestígios, sem mais notícias."
  },
