  CollectionHall_89411_Title = {Text = "Eclosão"},
  CollectionHall_89412_Desc = {
    Text = "O que antes estava diante de você agora está atrás de você. \nVocê sempre acreditou que depois de correr com todas as suas forças, esperando no final daquele tempo e espaço, com certeza estará aquelas mãos familiares e quentes."
