  },
  CollectionHall_89414_Desc = {
    Text = "Os heróis e a princesa correm sob o céu noturno, a brita sob seus pés conta a alegria da vida. Aquela coração, selado por mil anos, começa a bater lentamente com a passagem de uma estrela cadente."
