  },
  CollectionHall_89420_Title = {
    Text = "Rei Adormecido no Abismo"
  },
  CollectionHall_89706_Desc = {
    Text = "<Title:Resumo>\nÓrfã, de origem desconhecida, desde que tem memória foi adotada pelos tripulantes e viveu a bordo de um navio.\nDevido a essa experiência, Keposante desde criança sentia um desejo e curiosidade imensos pelo oceano.\nQuando cresceu, naturalmente escolheu uma profissão ligada ao mar e aos navios – tornou-se navegadora.\nDesde então, a jovem apaixonada pelo oceano passou a vagar eternamente sobre as águas, guiando os navios sob o brilho das estrelas.\nEla \"nasceu\" no oceano, a bordo de um navio.\nE também não teme \"morrer\" no oceano, a bordo de um navio.\nEssa é a sua vida."
  },
  CollectionHall_89706_LockTip = {
    Text = "Desbloqueie após despertar \"Kupersante\""
  },
  CollectionHall_89706_Title = {Text = "Corposant"},
  CollectionHall_89968_Desc = {
    Text = "Massacre, ódio, loucura e dor; o campo de batalha nunca carece disso. Quando você aposta sua vida na mesa de pôquer do monstro, deve pensar que tipo de vórtice carmesim isso irá causar."
  },
  CollectionHall_89968_LockTip = {
    Text = "Completar \"Sangue e Areia\" no Errante"
  },
  CollectionHall_89968_Title = {
    Text = "Vórtice Escarlate"
  },
  CollectionHall_89969_Desc = {
    Text = "Segundo a lenda, o navegador se transformará em um flash azul e branco acima do mastro após a morte, continuando a guiar a jornada do navio.\nQuando ela acendeu sua vida no topo do mastro, será que viu o caminho da esperança retornar?"
  },
  CollectionHall_89969_LockTip = {
    Text = "Complete a errância da consciência \"A Última Navegação\""
  },
  CollectionHall_89969_Title = {
    Text = "Fogo de Santo Elmo"
  },
  CollectionHall_89970_Desc = {
    Text = "Ela nasceu com um destino repleto de ódio, violência e conflitos incessantes.\nQuando ela abandona todas as ilusões brandas e quentes, optando por pegar armas e facas, o hino triunfante do destino já está sendo cantado em sua honra.\nEla foi destinada a se tornar uma guerreira, lavando seu ódio com o sangue dos inimigos, e assim viver uma vida que, embora talvez não seja gloriosa, será sem medo e sem arrependimentos."
  },
  CollectionHall_89970_LockTip = {
    Text = "Complete o registro especial \"Retornador de Elworth\""
  },
  CollectionHall_89970_Title = {
    Text = "Sangue por vingança"
  },
  CollectionHall_89971_Desc = {
    Text = "Sob o sol poente avermelhado, há areia amarela ensopada de sangue.\nO mais forte guerreiro está de pé no campo de batalha prestes a afundar na noite, relembrando as chamas douradas e a glória de outrora.\nIncontáveis abutres gritando se elevam, bloqueando os últimos raios de luz do sol. Na grande expedição oriental, o deserto está repleto de mortos-vivos, acompanhando-o na sepultura."
  },
  CollectionHall_89971_LockTip = {
    Text = "Complete \"Sangue e Areia\" em dificuldade Difícil em O Errante"
  },
  CollectionHall_89971_Title = {
    Text = "Sol Vermelho Banhado em Sangue"
  },
  CollectionHall_89972_Desc = {
    Text = "Se este mundo caiu na escuridão, então eu serei a última tocha.\nSe não há mais justiça entre a multidão, então eu falarei pelos mais fracos."
  },
  CollectionHall_89972_LockTip = {
    Text = "Complete a errância da consciência \"A Última Navegação\""
  },
  CollectionHall_89972_Title = {
    Text = "Tocha da Longa Noite"
  },
  CollectionHall_89973_Desc = {
    Text = "Aquela era sua batalha destinada, o campo de batalha que ela precisava alcançar.\nEla se despediu de toda fraqueza, hesitação e medo para abraçar o passado.\nEla não tem arrependimentos, pois compreendeu o verdadeiro significado de lutar nesta vida.\nEla não está sozinha; a lâmina em sua mão reflete o rosto furioso de outro eu."
  },
  CollectionHall_89973_LockTip = {
    Text = "Complete o registro especial \"Retorno de Elworth\" no nível de dificuldade Difícil"
  },
  CollectionHall_89973_Title = {
    Text = "Perguntar às Montanhas"
  },
  CollectionHall_89974_Desc = {
    Text = "Hey ho, hey ho, levante a âncora, hoiste as velas, desamarre a última corda.\nNosso navegador subiu ao mastro, e a bandeira colorida flutua alta.\nZarpe, zarpe, na direção que ela aponta, nós devemos zarpar!"
  },
  CollectionHall_89974_LockTip = {
    Text = "Complete a errância da consciência \"A Última Navegação\""
  },
  CollectionHall_89974_Title = {
    Text = "Diário do Navegador"
  },
  CollectionHall_89975_Desc = {
    Text = "Cada vez que ela parte, está preparada com a mais recente vontade.\nA canção que foi passada por gerações age como uma canção de ninar em um sonho, abraçando suavemente sua alma.\nAs bandeiras brilhantes tremulam ao vento; sua carne pode esfarelar, apodrecer, ou afundar no fundo do mar, mas sua alma certamente se manterá em seu navio, enviando uma luz eterna em direção às estrelas e ao mar."
  },
  CollectionHall_89975_LockTip = {
    Text = "Complete a errância da consciência \"A Última Navegação\""
  },
  CollectionHall_89975_Title = {
    Text = "Lamento do Navegador"
  },
  CollectionHall_89976_Desc = {
    Text = "No deserto de Kusi, a tempestade de areia é uma visitante constante; a areia que voa pelo ar invade as narinas e a boca dos vivos, e também enterra os corpos sem nome dos mortos. \n Apenas as feras que anseiam por carne humana farejam ansiosamente o vento, em busca do doce aroma de um banquete."
  },
  CollectionHall_89976_LockTip = {
    Text = "Completar \"Sangue e Areia\" no Errante"
  },
  CollectionHall_89976_Title = {
    Text = "Areia Amarela e Besta"
  },
  CollectionHall_89977_Desc = {
    Text = "O sol do deserto é diferente de outros lugares; é pálido, ofuscante e implacável, nunca mostrando um lado gentil. A besta não consegue imaginar a primavera que você descreve, então, por favor, vá ver por ela aquilo que você chama de verdadeiro sol."
  },
  CollectionHall_89977_LockTip = {
    Text = "Completar \"Sangue e Areia\" no Errante"
  },
  CollectionHall_89977_Title = {
    Text = "Sangue e Areia Sem Retorno"
  },
  CollectionHall_89978_Desc = {
    Text = "A neve infinita cai, dançando no ar, cobrindo o cabelo dos guerreiros com geada.\nNeste momento, as memórias de sua vida fluem; ela caminha das sutis profundezas dos corações humanos, dirigindo-se às altas montanhas.\nTraição, abandono e proteção, toda a dor e raiva são apenas uma série de batalhas. Com pessoas, com montanhas, e consigo mesma.\nEla olha para seu líder, para os novos companheiros, desconhecidos mas familiares, revelando um sorriso constrangido.\nUm dia ela pode triunfar, ou pode cair para sempre no campo de batalha, mas mesmo no momento de ascender ao céu ou descer ao inferno, ela não soltará a lâmina em sua mão.\nPara evitar perder tudo novamente, desta vez ela escolhe levantar a espada de proteção antes de buscar vingança, dirigindo-se sozinha ao seu campo de batalha."
  },
  CollectionHall_89978_LockTip = {
    Text = "Complete o registro especial \"Retornador de Elworth\""
  },
  CollectionHall_89978_Title = {
    Text = "Para um amanhã sem novas perdas"
  },
  CollectionHall_89998_LockTip = {
    Text = "Precisa completar qualquer fase da atividade por tempo limitado \"A sombra que espreita o Reino Divino: Maré Anômala\""
  },
  CollectionHall_89998_Title = {
    Text = "A sombra que espreita o Reino Divino: Maré Anômala"
  },
  CollectionHall_89999_LockTip = {
    Text = "Precisa completar qualquer fase da atividade por tempo limitado \"Prisioneiro do Espelho: Voo pelo céu azul\""
  },
  CollectionHall_89999_Title = {
    Text = "Prisioneiro do Espelho: Voo pelo Céu Azul"
  },
  CollectionHall_90245_LockTip = {
    Text = "Limpar Paisagem dos Sonhos: Desbloquear qualquer ponto de verificação de \"Além dos Céus: Parte I\""
  },
  CollectionHall_90245_Title = {
    Text = "Antes que o pássaro caia"
  },
  CollectionHall_90415_Title = {
    Text = "Além do Horizonte - Parte 1"
  },
  CollectionHall_90416_Desc = {
    Text = "<Title:Resumo>\nUm dos vários produtos experimentais criados pela Igreja da Luz do Templo para o ritual de invocação de deuses, ele teve a sorte de nascer como gêmeo, evitando assim o destino de ser descartado como lixo.\nDesde pequeno, junto com seu irmão Pólux, foi reverenciado como o Filho Sagrado e submetido a uma rígida disciplina, recebendo constantemente ensinamentos teológicos sobre o Portador da Lanterna. O único contato que tiveram com informações sobre o mundo exterior foi um livro ricamente ilustrado e de capa pesada oferecido por um fiel.\nNa adolescência, após seu irmão ser submetido a um cruel ritual de modificação pela igreja, os dois decidiram fugir juntos em busca de liberdade, mas foram rapidamente capturados e trazidos de volta.\nEle foi mergulhado em uma piscina corrosiva chamada \"Lago do Pecado\", onde foi submetido à \"terapia do pecado\" para cicatrizar seus ferimentos, passando por um longo período de tortura.\nComo resultado, ele acabou esquecido pelas pessoas, exceto por Juliette, incluindo seu irmão Pólux, e seu relacionamento com o irmão tornou-se frio e distante.\nDesde então, ele se manteve em silêncio, fingindo obediência à igreja, mas em seu coração nunca desistiu de seu desejo de fugir novamente com seu irmão, esperando pacientemente pela oportunidade de recuperar sua liberdade."
  },
  CollectionHall_90416_LockTip = {
    Text = "Desbloquear após despertar \"Castor\""
  },
  CollectionHall_90416_Title = {Text = "Castor"},
  CollectionHall_94552_LockTip = {
    Text = "É necessário concluir qualquer fase da atividade por tempo limitado \"Grande Conquista: Caça Sagrada\""
  },
  CollectionHall_94552_Title = {
    Text = "Grande Conquista: Caça Sagrada"
  },
  CollectionHall_94553_Desc = {
    Text = "A Igreja da Luz do Templo cultivou artificialmente um par de gêmeos para o ritual de invocação divina. Quando foi considerado um fracasso no experimento e estava prestes a ser cruelmente abandonado, ele nasceu através da divisão da carne e do sangue de seu irmão.\nEsse tipo de apego instintivo à sobrevivência não foi sorte, mas sim alterou o destino dos dois irmãos, transformando uma tragédia breve em uma tragédia ainda mais longa.\nTalvez por conta do mistério da gemelaridade, sua pele e personalidade eram exatamente opostas às de seu irmão. Como o mais ativo e esperto dos gêmeos, sempre cometia ações rebeldes contrárias às disciplinas, parecendo um garoto travesso em uma família comum — até ser escolhido para ser cultivado como recipiente da divindade e começar a passar periodicamente pelos dolorosos e sangrentos rituais de \"reforma sagrada\".\nIncapaz de suportar o sofrimento e o destino desesperançoso, após anos de súplicas e planejamento, os dois irmãos, por meio de códigos secretos, finalmente conseguiram escapar após superar inúmeros obstáculos.\nNo entanto, eles não ficaram felizes por muito tempo e foram capturados novamente pelos perseguidores da igreja. Ordens foram dadas por Ariette para remover as asas livres dele e submetê-lo a uma lavagem cerebral extrema, fazendo com que ele esquecesse completamente seu irmão e passasse a desfrutar da sensação de ser venerado como o filho sagrado.\nSomente após uma segunda fuga, com a morte do irmão e o efeito do ritual de invocação divina, ele recuperou a memória, e seu \"coração sagrado\" foi incendiado pelo ódio e pela fúria, tomando como nova direção em sua vida o combate contra a Igreja da Luz do Templo."
  },
  CollectionHall_94553_LockTip = {
    Text = "Limpe a Paisagem dos sonhos \"Além do Horizonte: Inferior\" para desbloquear"
  },
  CollectionHall_94553_Title = {Text = "Pollux"},
  CollectionHall_95436_Desc = {
    Text = "Voe, voe, os pássaros usam suas asas para lutar contra a pesada gravidade, constantemente planando, planando, atravessando correntes de ar turbulentas e redemoinhos, indo em direção a lugares mais altos.\nNo entanto, ele não sabe que um fio invisível foi amarrado aos seus pés; talvez ele nunca tenha realmente se tornado um pássaro; mesmo que voe, ele é meramente uma pálida pipa.\nAgora, a linha da pipa se apertou."
  },
  CollectionHall_95436_LockTip = {
    Text = "Complete a Paisagem dos Sonhos \"Além do Horizonte: Superior\""
  },
  CollectionHall_95436_Title = {Text = "pipa"},
  CollectionHall_95437_Desc = {
    Text = "Você viu aquele rosto, aquele rosto gentil, sereno e belo. \nEle logo se dissolveu em sua memória, mas você sempre se lembrará da cor suave da luz da manhã após aquela longa noite de chuva.\n\n."
  },
  CollectionHall_95437_LockTip = {
    Text = "Complete o registro especial \"Sombra da Cidade da Chuva\""
  },
  CollectionHall_95437_Title = {
    Text = "Nas profundezas da cortina de chuva"
  },
  CollectionHall_95438_Desc = {
    Text = "Seja um gato, um gato despreocupado, apenas ficando com aqueles que você ama, encolhendo-se ao lado dela todos os dias para se aquecer ao sol.\nEste é o seu lindo pequeno sonho no coração, mas a beleza sempre permanece uma coisa tão frágil e delicada."
  },
  CollectionHall_95438_LockTip = {
    Text = "Complete o registro especial \"Fissão Tranquila\""
  },
  CollectionHall_95438_Title = {
    Text = "Desejo do Gato"
  },
  CollectionHall_95439_Desc = {
    Text = "Mesmo que o mundo se transforme em cinzas, mesmo que tudo se dissolva no Limo d, as inocentes águas-vivas podem imergir eternamente em seus próprios sonhos.\nLá, tudo é como era. Apenas risos. Apenas alegria."
  },
  CollectionHall_95439_LockTip = {
    Text = "Complete \"Everything as Usual\" no nível Difícil em The Wandering"
  },
  CollectionHall_95439_Title = {
    Text = "Imerso na deslumbrante desordem do caos"
  },
  CollectionHall_95440_Desc = {
    Text = "Lentini raramente neva no inverno, e cada nevada causa uma alegria contagiante entre as crianças.\nVocê acorda de um longo sonho suave e estende a mão para fora da janela. Um floco de neve cai em sua palma e se dissolve contente com o calor.\nOs flocos de neve caem abundantemente, após uma breve jornada pelo céu, retornando à terra, ao rio subterrâneo e ao ciclo de todas as gotas d'água.\nNa primeira grande nevada deste ano, ela também retornou para casa.\nBoa noite, neve; boa noite, \"24\"."
  },
  CollectionHall_95440_LockTip = {
    Text = "Complete o registro especial \"Fissão Tranquila\""
  },
  CollectionHall_95440_Title = {
    Text = "Boa noite, neve"
  },
  CollectionHall_95441_Desc = {
    Text = "Ramos de coral Branco estendem-se para fora, crescendo palácios brancos puros.\nNos colunas distorcidas, peixes coloridos nadam livremente.\nO Corpo está afundando, a alma está flutuando.\nVocê perde a respiração voluntariamente, afundando junto com ela, perdido em um sonho branco.\nEsse é o milagre do mar, essa é a calorosa e azul pátria."
  },
  CollectionHall_95441_LockTip = {
    Text = "Complete \"Sculpting a Song\" na errante"
  },
  CollectionHall_95441_Title = {
    Text = "Palácio Branco"
  },
  CollectionHall_95442_Desc = {
    Text = "Ding ding——O trenzinho parte!\nDeixe-me levar meus amigos ao reino eterno dos contos de fadas alegres sem dor."
  },
  CollectionHall_95442_LockTip = {
    Text = "Completar \"Tudo como Sempre\" na errância"
  },
  CollectionHall_95442_Title = {
    Text = "Sonho inocente e tolo"
  },
  CollectionHall_95443_Desc = {
    Text = "Ela é a assassina? Ela se parece com uma amante há muito perdida.\nChuva, folhas mortas e um toque de uma fragrância floral sonhadora; você abre as narinas, tentando sentir um cheiro de sangue entre aquelas fragrâncias úmidas como evidência de sua culpa. No entanto, você não sentiu nada.\nEla nunca teve a intenção de explicar, em meio à névoa, você caiu em seu sonho cinza."
  },
  CollectionHall_95443_LockTip = {
    Text = "Complete o registro especial \"Sombra da Cidade da Chuva\""
  },
  CollectionHall_95443_Title = {Text = "Suspeito"},
  CollectionHall_95444_Desc = {
    Text = "Essa mesma sede ela também experimentou.\nIngênua, selvagem e solitária.\nEla teve sorte; ela terminou sua longa vagabundagem, ganhando memórias quentes para saborear por toda a vida.\nAgora ela pega a mão de um espírito afim, enviando essa alma errante a um sono tranquilo."
  },
  CollectionHall_95444_LockTip = {
    Text = "Complete o registro especial \"Sombra da Cidade da Chuva\" no nível de dificuldade Difícil"
  },
  CollectionHall_95444_Title = {
    Text = "Sonho da Besta"
  },
  CollectionHall_95445_Desc = {
    Text = "Do meu punhal, cravado no meu coração.\nDiante do destino implacável e da vida amarga, sou tão pequeno, fraco e impotente.\nPor que devo ser eu? Estou indo bem como eu mesmo?\nDas minhas perguntas, também sou incapaz de responder."
  },
  CollectionHall_95445_LockTip = {
    Text = "Complete o registro especial \"Fissão Tranquila\""
  },
  CollectionHall_95445_Title = {
    Text = "Pergunte-me"
  },
  CollectionHall_95446_Desc = {
    Text = "Huh? Você parece diferente de antes? \nÉ que seus olhos estão mais brilhantes? Ou é que sua disposição está mais viva? Ou o proprietário deste invólucro medíocre já mudou sua alma?"
  },
  CollectionHall_95446_LockTip = {
    Text = "Complete \"Sculpting a Song\" na errante"
  },
  CollectionHall_95446_Title = {
    Text = "Transferência de Alma"
  },
  CollectionHall_95447_Desc = {
    Text = "Seja nevando, chovendo, ensolarado ou nublado, o rio continua fluindo calmamente hoje."
  },
  CollectionHall_95447_LockTip = {
    Text = "Complete o registro especial \"Fissão Tranquila\""
  },
  CollectionHall_95447_Title = {
    Text = "Rio Tranquilo"
  },
  CollectionHall_95448_Desc = {
    Text = "A maré sobe, cabeças gritam.\nPares de olhos te encaram, rostos te amaldiçoam.\nEles querem te afogar, eles querem te devorar.\nVocê fecha os olhos temerosamente, e quando os abre novamente, descobre que estão bem ao seu lado."
  },
  CollectionHall_95448_LockTip = {
    Text = "Complete o registro especial \"Sombra da Cidade da Chuva\""
  },
  CollectionHall_95448_Title = {
    Text = "Mar de cabeças"
  },
  CollectionHall_95449_Desc = {
    Text = "Ela prometeu a você que certamente o levaria para casa junto com ela. \n— Retornar com postura eterna à terra natal tranquila, repleta de milagres e beleza."
  },
  CollectionHall_95449_LockTip = {
    Text = "Complete \"Sculpting a Song\" na errante"
  },
  CollectionHall_95449_Title = {
    Text = "Arte da petrificação"
  },
  CollectionHall_95450_Desc = {
    Text = "Aquele ilustre convidado, olhando para as costas cheias de esperança de Cástor, sussurrou suavemente sob a luz da lua a profecia do destino: \"Ele sairá, lutará desesperadamente contra a tempestade. O que o fizer voar alto, também o fará cair.\""
  },
  CollectionHall_95450_LockTip = {
    Text = "Complete a Paisagem dos Sonhos \"Além do Horizonte: Superior\""
  },
  CollectionHall_95450_Title = {
    Text = "Na tempestade"
  },
  CollectionHall_95451_Desc = {
    Text = "Nascida na beleza, morrendo na beleza.\nEla é um gênio, uma louca, um diabo; ela é a executor frio e sem coração, e também sua doce família.\nCom amor fervoroso, ela molda você em uma obra-prima perfeita.\nEla te abraça, pega sua mão fria. Ela vai te levar de volta à terra natal da arte com ela"
  },
  CollectionHall_95451_LockTip = {
    Text = "Complete \"Sculpting a Song\" no nível Difícil em The Wandering"
  },
  CollectionHall_95451_Title = {
    Text = "Morte da Beleza"
  },
  CollectionHall_95452_Desc = {
    Text = "O oceano ouviu meu chamado, trazendo você para o meu lado.\nA partir de então, conversamos, brincamos e nos alegramos livremente, destinados a nos tornarmos os melhores amigos do mundo.\nNesta cidade cheia de dissolução e silêncio mortal."
  },
  CollectionHall_95452_LockTip = {
    Text = "Completar \"Tudo como Sempre\" na errância"
  },
  CollectionHall_95452_Title = {
    Text = "Por favor, seja meu amigo"
  },
  CollectionHall_95453_Desc = {
    Text = "Voltem, todas as versões corajosas, covardes, inteligentes, tolas, fortes e fracas de mim.\nDeixemos todos os corações alegres, tristes, irados, doloridos e cansados derreterem.\nEstamos juntos.\nEles estão juntos para sempre."
  },
  CollectionHall_95453_LockTip = {
    Text = "Complete o registro especial \"Fissão Tranquila\" no nível de dificuldade Difícil"
  },
  CollectionHall_95453_Title = {
    Text = "Retorne a ela"
  },
  CollectionHall_95454_Desc = {
    Text = "Essa vazio e fenda que vem da alma só podem ser preenchidos pelo conto de fadas mais puro.\nUm dia, ela dirá adeus à dor e retornará ao \"lar\" cheio de alegria do conto de fadas."
  },
  CollectionHall_95454_LockTip = {
    Text = "Completar \"Tudo como Sempre\" na errância"
  },
  CollectionHall_95454_Title = {
    Text = "Conto de terror inocente"
  },
  CollectionHall_95455_Desc = {
    Text = "Aquelas vielas sombrias e estreitas, obscurecidas pela escuridão, sempre carregam muitos momentos de pontos de virada do destino. Reencontros, discussões, separações, até mesmo violência, bullying e assassinato.\nFelizmente, a história de hoje não incluiu as cenas sangrentas da parte final, mas quem pode dizer que o que a precedeu não levou a uma verdadeira tragédia?"
  },
  CollectionHall_95455_LockTip = {
    Text = "Complete a Paisagem dos Sonhos \"Além do Horizonte: Superior\""
  },
  CollectionHall_95455_Title = {
    Text = "Beco Escuro"
  },
